# ============================================================
# Targeted 3did domain-mediated interaction analysis
# Salinity-responsive isoform switching in Arabidopsis thaliana
# ============================================================

library(dplyr)

# ------------------------------------------------------------
# Load final Pfam annotations generated by script 05
# ------------------------------------------------------------

pfam_domains <- read.csv(
  "results/Pfam_collapsed_domain_annotations.csv",
  stringsAsFactors = FALSE
)

# ------------------------------------------------------------
# Representative isoform pairs examined with 3did
# ------------------------------------------------------------

representative_pairs <- data.frame(
  gene_id = c(
    "AT1G50700",
    "AT2G23380",
    "AT2G26650",
    "AT2G41830",
    "AT3G48150",
    "AT3G59100"
  ),
  control_isoform = c(
    "AT1G50700.1",
    "AT2G23380.1",
    "AT2G26650.1",
    "AT2G41830.1",
    "AT3G48150.1",
    "AT3G59100.2"
  ),
  salt_isoform = c(
    "AT1G50700.3",
    "AT2G23380.2",
    "AT2G26650.2",
    "AT2G41830.2",
    "AT3G48150.2",
    "AT3G59100.1"
  ),
  stringsAsFactors = FALSE
)

# ------------------------------------------------------------
# Import parsed 3did domain-domain interaction table
# ------------------------------------------------------------
# This file should contain one structurally supported interaction
# per row with two Pfam accessions:
#
# domain_1    domain_2
# PFxxxxx     PFyyyyy
#
# The file was derived from the 3did domain-domain interaction
# dataset used in the manuscript.

three_did <- read.delim(
  "data/external_predictions/3did_domain_interactions.tsv",
  header = TRUE,
  sep = "\t",
  stringsAsFactors = FALSE
)

# ------------------------------------------------------------
# Function: retrieve 3did-supported partner-domain repertoire
# for one protein isoform
# ------------------------------------------------------------

get_partner_domains <- function(protein_id) {

  protein_domains <- pfam_domains %>%
    dplyr::filter(
      protein_id == !!protein_id
    ) %>%
    dplyr::pull(signature_accession) %>%
    unique()

  partners <- three_did %>%
    dplyr::filter(
      domain_1 %in% protein_domains |
        domain_2 %in% protein_domains
    ) %>%
    dplyr::mutate(
      partner = dplyr::case_when(
        domain_1 %in% protein_domains ~ domain_2,
        domain_2 %in% protein_domains ~ domain_1,
        TRUE ~ NA_character_
      )
    ) %>%
    dplyr::pull(partner) %>%
    unique() %>%
    stats::na.omit() %>%
    as.character()

  sort(partners)
}

# ------------------------------------------------------------
# Compare partner-domain repertoires
# ------------------------------------------------------------

interaction_results <- lapply(
  seq_len(nrow(representative_pairs)),
  function(i) {

    gene <- representative_pairs$gene_id[i]
    control <- representative_pairs$control_isoform[i]
    salt <- representative_pairs$salt_isoform[i]

    control_partners <- get_partner_domains(control)
    salt_partners <- get_partner_domains(salt)

    shared <- intersect(
      control_partners,
      salt_partners
    )

    control_unique <- setdiff(
      control_partners,
      salt_partners
    )

    salt_unique <- setdiff(
      salt_partners,
      control_partners
    )

    union_set <- union(
      control_partners,
      salt_partners
    )

    jaccard <- if (
      length(union_set) == 0
    ) {
      NA_real_
    } else {
      length(shared) / length(union_set)
    }

    data.frame(
      gene_id = gene,
      control_isoform = control,
      salt_isoform = salt,
      n_control_partner_domains = length(control_partners),
      n_salt_partner_domains = length(salt_partners),
      n_shared = length(shared),
      n_control_unique = length(control_unique),
      n_salt_unique = length(salt_unique),
      jaccard_similarity = jaccard,
      control_unique_domains = paste(
        control_unique,
        collapse = ";"
      ),
      salt_unique_domains = paste(
        salt_unique,
        collapse = ";"
      ),
      stringsAsFactors = FALSE
    )
  }
)

interaction_results <- dplyr::bind_rows(
  interaction_results
)

interaction_results

# ------------------------------------------------------------
# Inspect GSL11 / AT3G59100 specifically
# ------------------------------------------------------------

gsl11_result <- interaction_results %>%
  dplyr::filter(
    gene_id == "AT3G59100"
  )

gsl11_result

# ------------------------------------------------------------
# Export
# ------------------------------------------------------------

dir.create(
  "results",
  showWarnings = FALSE,
  recursive = TRUE
)

write.csv(
  interaction_results,
  "results/3did_representative_isoform_pairs.csv",
  row.names = FALSE
)

capture.output(
  sessionInfo(),
  file = "results/3did_analysis_sessionInfo.txt"
)
